function nk(s) { return String(s == null ? '' : s).trim().toLowerCase(); }
const rows = $input.all().map(function (i) { return i.json; });

let total = rows.length, shared = 0, notShared = 0, paused = 0, respond = 0;
let fu1 = 0, fu2 = 0, fu3 = 0, dueOnOrBefore20260908 = 0;
const byOwnerShared = {}, byOwnerPending = {};

for (const r of rows) {
  const own = String(r.owner == null ? '' : r.owner).trim() || '(blank)';
  const isShared = nk(r.deal_shared) === 'yes';
  if (String(r.pause == null ? '' : r.pause).trim() !== '') { paused++; }
  if (nk(r.investor_response) !== '') { respond++; }
  if (isShared) {
    shared++;
    byOwnerShared[own] = (byOwnerShared[own] || 0) + 1;
    if (nk(r.fu1_done) === 'yes') fu1++;
    if (nk(r.fu2_done) === 'yes') fu2++;
    if (nk(r.fu3_done) === 'yes') fu3++;
  } else {
    notShared++;
    byOwnerPending[own] = (byOwnerPending[own] || 0) + 1;
    const d = String(r.next_due == null ? '' : r.next_due).trim();
    if (d && d <= '2026-09-08') dueOnOrBefore20260908++;
  }
}

return [{ json: {
  total_rows: total,
  deal_shared_yes: shared,
  deal_shared_no: notShared,
  pct_shared: Math.round(shared / total * 1000) / 10,
  paused_rows: paused,
  rows_with_investor_response: respond,
  of_shared_fu1_done: fu1,
  of_shared_fu2_done: fu2,
  of_shared_fu3_done: fu3,
  unsent_due_on_or_before_2026_09_08: dueOnOrBefore20260908,
  shared_by_owner: byOwnerShared,
  pending_by_owner: byOwnerPending
}}];
